% Divergence: introduce per-cell coverage indicators (left/right/up/down) tied to domino starts so each cell sees exactly one coverage direction instead of summing neighbor starts directly.
int: m;
int: n;

array[1..m, 1..n - 1] of var bool: h;
array[1..m - 1, 1..n] of var bool: v;

array[1..m, 1..n] of var bool: cover_left;
array[1..m, 1..n] of var bool: cover_right;
array[1..m, 1..n] of var bool: cover_up;
array[1..m, 1..n] of var bool: cover_down;

constraint forall(i in 1..m, j in 1..n - 1)(
  cover_right[i, j] = h[i, j]
);
constraint forall(i in 1..m, j in 2..n)(
  cover_left[i, j] = h[i, j - 1]
);
constraint forall(i in 1..m)(
  cover_left[i, 1] = false /\
  cover_right[i, n] = false
);

constraint forall(i in 1..m - 1, j in 1..n)(
  cover_down[i, j] = v[i, j]
);
constraint forall(i in 2..m, j in 1..n)(
  cover_up[i, j] = v[i - 1, j]
);
constraint forall(j in 1..n)(
  cover_up[1, j] = false /\
  cover_down[m, j] = false
);

constraint forall(i in 1..m, j in 1..n)(
  bool2int(cover_left[i, j]) +
  bool2int(cover_right[i, j]) +
  bool2int(cover_up[i, j]) +
  bool2int(cover_down[i, j]) = 1
);

solve satisfy;

output [
  "h=\n", show(h), "\n",
  "v=\n", show(v), "\n"
];

