# Strategy: use cell-wise orientation links (dual view) plus adjacency implications for propagation
from cpmpy import *

m = 4
n = 6

orientation = intvar(0, 3, shape=(m, n), name="orientation")
h = boolvar(shape=(m, n - 1), name="h")
v = boolvar(shape=(m - 1, n), name="v")

model = Model()

for i in range(m):
    for j in range(n):
        if j == n - 1:
            model += (orientation[i, j] != 0)
        if j == 0:
            model += (orientation[i, j] != 1)
        if i == m - 1:
            model += (orientation[i, j] != 2)
        if i == 0:
            model += (orientation[i, j] != 3)

        if j < n - 1:
            model += (orientation[i, j] == 0).implies(orientation[i, j + 1] == 1)
        if j > 0:
            model += (orientation[i, j] == 1).implies(orientation[i, j - 1] == 0)
        if i < m - 1:
            model += (orientation[i, j] == 2).implies(orientation[i + 1, j] == 3)
        if i > 0:
            model += (orientation[i, j] == 3).implies(orientation[i - 1, j] == 2)

for i in range(m):
    for j in range(n - 1):
        model += (h[i, j] == (orientation[i, j] == 0))

for i in range(m - 1):
    for j in range(n):
        model += (v[i, j] == (orientation[i, j] == 2))

if model.solve():
    print(h.value())
    print(v.value())

